package app.cryptoresearch.mobile;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.content.Intent;import android.os.SystemClock;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @LooperMode(LooperMode.Mode.PAUSED)
public class BackgroundTests {
 public static class SilentService extends PaperBackgroundService {protected void openSocket(){}}
 org.robolectric.android.controller.ServiceController<SilentService> controller;SilentService service;
 @Before public void setup(){PaperBackgroundService.session=null;PaperBackgroundService.transferCandidate=null;PaperBackgroundService.active=false;controller=Robolectric.buildService(SilentService.class).create();service=controller.get();}
 @After public void cleanup(){controller.destroy();PaperBackgroundService.session=null;PaperBackgroundService.transferCandidate=null;PaperBackgroundService.active=false;}
 Intent start(){return new Intent(service,SilentService.class).setAction(PaperBackgroundService.START).putExtra("symbol","BTC").putExtra("capital",1000000.).putExtra("fee",5.).putExtra("slip",5.);}
 @Test public void startAndStopPreservesReport(){service.onStartCommand(start(),0,1);assertTrue(PaperBackgroundService.active);assertNotNull(service.notice().actions);assertEquals("중지",service.notice().actions[0].title.toString());service.onStartCommand(new Intent().setAction(PaperBackgroundService.STOP),0,2);assertFalse(PaperBackgroundService.active);assertFalse(PaperBackgroundService.session.running);assertTrue(new java.io.File(service.getFilesDir(),"background-paper-last.json").exists());}
 @Test public void transferPreservesSameBook(){StrategyCore.Live p=new StrategyCore.Live("BTC",1000000,5,5);p.engine.bars=23;p.engine.cash=900000;p.engine.qty=2;PaperBackgroundService.transferCandidate=p;service.onStartCommand(start().putExtra("transfer",true),0,1);assertSame(p,PaperBackgroundService.session);assertEquals(23,p.engine.bars);assertEquals(2,p.engine.qty,0);assertTrue(PaperBackgroundService.owns(p));}
 @Test public void androidTimeoutStopsWithoutForcedFill(){service.onStartCommand(start(),0,1);PaperBackgroundService.session.engine.qty=1;service.onTimeout(1,1);assertFalse(PaperBackgroundService.active);assertEquals(1,PaperBackgroundService.session.engine.qty,0);assertFalse(PaperBackgroundService.session.running);}
 @Test public void hardLimitRespected(){service.onStartCommand(start(),0,1);service.startedElapsed=SystemClock.elapsedRealtime()-PaperBackgroundService.LIMIT_MS-1;service.clock.run();assertFalse(PaperBackgroundService.active);}
 @Test public void badGenerationCannotMutate(){service.onStartCommand(start(),0,1);long n=System.currentTimeMillis();service.acceptFrame(service.generation-1,n,n,100);assertEquals(0,service.lastReceive);}
 @Test public void duplicateStartDoesNotReset(){service.onStartCommand(start(),0,1);StrategyCore.Live original=PaperBackgroundService.session;original.engine.bars=20;service.onStartCommand(start(),0,2);assertSame(original,PaperBackgroundService.session);assertEquals(20,original.engine.bars);}
 @Test public void invalidSymbolCannotStart(){service.onStartCommand(start().putExtra("symbol","BTC/OTHER"),0,1);assertFalse(PaperBackgroundService.active);}
 @Test public void secureServerAddressPolicy()throws Exception{assertEquals("https://gram.example.com",PaperServerAPI.canonical("https://gram.example.com/"));for(String raw:new String[]{"http://gram.example.com","https://u:p@gram.example.com","https://gram.example.com/path","https://gram.example.com?token=x","https://gram.example.com#x"})assertThrows(Exception.class,()->PaperServerAPI.canonical(raw));}
 @Test public void backgroundPanelIsNativeAndOffline(){android.app.Activity activity=Robolectric.buildActivity(BackgroundActivity.class).create().get();assertNotNull(((BackgroundActivity)activity).localStatus);assertFalse(((BackgroundActivity)activity).busy);activity.finish();}
}
